def _identity_stmt(self, stmt: Statement, sctx: SchemaContext) -> None:
        """Handle identity statement."""
        if not isinstance(stmt, Identity):
            raise ValueError(f'Expected Identity, got {type(stmt)}')

        if stmt.identity_name is None:
            raise ValueError('identity_name is required')

        if stmt.identity_name in self.identities:
            raise ValueError(f'identity {stmt.identity_name} already exists')

        self.identities[stmt.identity_name] = stmt

